// {count, source, fetched} for a benchmark, or null when the lookup found no
// confident match. Never guess a number here: an absent count renders as
// "not available" rather than as zero.
export function citationInfo(key) {
  const paper = citations.papers?.[key]
  if (!paper || paper.count == null) return null
  return {
    count: paper.count,
    source: citations._source,
    fetched: citations._fetched,
    versionsSeen: paper.versions_seen,
  }
}

export const CITATION_CAVEAT =
  'Counts come from OpenAlex, which sometimes files a preprint and its published version as separate works and splits the count between them. Treat each as a lower bound. Re-run dashboard/scripts/fetch_benchmark_citations.py to refresh.'
